// packages/core/src/openapi/bridge.ts
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { ListToolsRequestSchema, CallToolRequestSchema, McpError, ErrorCode } from '@modelcontextprotocol/sdk/types.js';

export async function createOpenApiTransport(
  cfg: OpenApiServerConfig,
  deps: { getSecret(ref: string): Promise<string>; safeFetch: SafeFetch },
): Promise<Transport> {
  const doc  = await loadSpec(cfg, deps.safeFetch);          // spec.ts
  const { ops, skipped } = buildOperations(doc, cfg);        // operations.ts
  const byName = new Map(ops.map(o => [o.name, o]));

  const server = new Server({ name: 'openapi', version: doc.info.version ?? '0.0.0' },
                            { capabilities: { tools: {} } });
  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: ops.map(o => ({ name: o.name, description: o.description, inputSchema: o.inputSchema })),
  }));
  server.setRequestHandler(CallToolRequestSchema, async (req) => {
    const op = byName.get(req.params.name);
    if (!op) throw new McpError(ErrorCode.InvalidParams, TOOL_UNAVAILABLE_MESSAGE); // same text core uses
    return callOperation(op, req.params.arguments ?? {}, cfg, deps);               // request.ts
  });

  const [clientSide, serverSide] = InMemoryTransport.createLinkedPair();
  await server.connect(serverSide);
  return clientSide;   // core connects a normal Client to this, identical to stdio/http
}

// packages/core/src/openapi/operations.ts
export interface OperationSpec {
  name: string; description?: string; method: string; path: string;
  params: { name: string; in: 'path'|'query'|'header'|'cookie'; required: boolean; style?: string; explode?: boolean }[];
  bodyContentType?: 'application/json'|'application/x-www-form-urlencoded';
  inputSchema: JsonSchema;   // { type:'object', properties, required, $defs? }
  security?: SecurityRequirement[];   // op-level overrides root
}
export function buildOperations(doc: OpenApiDoc, cfg: OpenApiServerConfig):
  { ops: OperationSpec[]; skipped: { id: string; reason: string }[] };

function toolNameFor(op: {operationId?: string; method: string; path: string}, taken: Set<string>): string {
  const base = (op.operationId ?? `${op.method}_${op.path}`)
    .replace(/\{([^}]+)\}/g, '$1')
    .replace(/[^A-Za-z0-9_]+/g, '_')
    .replace(/^_+|_+$/g, '').slice(0, 60) || 'op';
  let n = 2, name = base;
  while (taken.has(name)) name = `${base}_${n++}`;
  taken.add(name); return name;
}

/** Walk $refs from `schema`, pull ONLY reachable component schemas into $defs. */
function attachDefs(schema: JsonSchema, components: Record<string, JsonSchema>): JsonSchema {
  const want = new Set<string>(); const queue = [schema];
  while (queue.length) for (const r of refsIn(queue.pop()!)) {
    const n = r.replace('#/$defs/', '');
    if (!want.has(n) && components[n]) { want.add(n); queue.push(components[n]); }
  }
  return want.size ? { ...schema, $defs: Object.fromEntries([...want].map(n => [n, components[n]])) } : schema;
}

// packages/core/src/openapi/request.ts
export async function callOperation(op: OperationSpec, args: Record<string, unknown>,
                                    cfg: OpenApiServerConfig, deps: Deps): Promise<CallToolResult> {
  const base = new URL(cfg.baseUrl ?? op.defaultBaseUrl);
  let path = op.path;
  for (const p of op.params) if (p.in === 'path')
    path = path.replace(`{${p.name}}`, encodeURIComponent(String(args[p.name] ?? '')));
  const url = new URL(base.pathname.replace(/\/$/, '') + path, base);
  if (url.origin !== base.origin)                       // path-param escape guard
    throw new McpError(ErrorCode.InvalidParams, 'resolved URL left the configured origin');

  for (const p of op.params) if (p.in === 'query') appendQuery(url, p, args[p.name]); // style:form only
  const headers = new Headers(); const init: RequestInit = { method: op.method, headers,
    redirect: 'manual', signal: AbortSignal.timeout(30_000) };
  applySecurity(op, cfg, headers, url, deps);                                  // security.ts
  if (op.bodyContentType) setBody(init, headers, op, args.body);

  const res = await followSafe(url, init, deps, /*maxHops*/ 3); // assertSafeUrl + same-origin per hop
  const text = await readCapped(res, 256 * 1024);               // aborts the stream at the cap
  return res.ok
    ? { content: [{ type: 'text', text: pretty(text, res.headers.get('content-type')) }] }
    : { isError: true, content: [{ type: 'text', text: `HTTP ${res.status} ${res.statusText}\n${text}` }] };
}

